import{j as e}from"./vendor-query-4Od-xAjI.js";import{o as s}from"./index-BecjsGbS.js";import{B as r}from"./BottomNavigation-Br9BNbIE.js";import{B as c}from"./button-Cw29ihGg.js";import{u as d}from"./vendor-react-q5QseVhI.js";import{A as l}from"./arrow-right-B07h3kCe.js";import{A as m}from"./arrow-left-CwJda9hc.js";import"./vendor-supabase-Cv0iAapC.js";import"./vendor-motion-BkSUeLYQ.js";import"./briefcase-B3DXagAD.js";import"./bell-DuIIgATp.js";import"./user-DvgGMuaC.js";function D(){const{isRTL:t}=s(),i=d(),n=t?[{t:"مقدمة",c:"تطبيق Sovereign يحترم خصوصيتك. نلتزم بحماية بياناتك الشخصية وفقاً لأعلى المعايير الدولية بما في ذلك GDPR (الاتحاد الأوروبي) و CCPA (كاليفورنيا). Sovereign منصة تواصل تجاري للمشاهير والوكلاء والشركات — لا توجد رسائل عامة، لا تغذية اجتماعية، ولا رسائل مباشرة بدون عرض مقبول."},{t:"البيانات التي نجمعها",c:"نجمع البيانات التالية لتقديم الخدمة: البريد الإلكتروني، اسم المستخدم، الاسم الظاهر، صورة الملف الشخصي، الرسائل المرسلة والمستلمة (مشفرة من طرف إلى طرف)، بطاقات العروض (Deal Cards) وتفاصيلها (نوع العرض، اسم الشركة، نطاق الميزانية، الجدول الزمني، المخرجات، الحصرية، السبب)، روابط الوكالة بين المشاهير والوكلاء، مفاتيح التشفير العامة، وإعدادات الحساب. لا نجمع: بيانات الموقع، جهات الاتصال، سجل المكالمات، بيانات الدفع، أو أي بيانات حساسة أخرى."},{t:"كيف نستخدم بياناتك",c:"نستخدم بياناتك فقط لـ: تقديم خدمة التواصل التجاري وإدارة عروض العمل، تصنيف الرسائل الواردة إلى صندوق العمل باستخدام الذكاء الاصطناعي، إرسال الإشعارات (دفع، بريد إلكتروني) للعروض والرسائل الجديدة، منع الإساءة والاحتيال وتطبيق حدود الإرسال في صندوق العمل، وتمكين تفويض الوكلاء لإدارة المحادثات نيابة عن المشاهير. لا نبيع أو نشارك بياناتك مع أطراف ثالثة لأغراض إعلانية مطلقاً."},{t:"الذكاء الاصطناعي وتصنيف الرسائل",c:"نستخدم الذكاء الاصطناعي لتصنيف الرسائل الواردة إلى صندوق العمل فقط. التصنيف يتم على محتوى الرسائل مؤقتاً ولا يُخزّن النص الأصلي بعد التصنيف. لا نستخدم رسائلك أو بطاقات العروض لتدريب نماذج الذكاء الاصطناعي."},{t:"تشفير الرسائل",c:"جميع الرسائل وبطاقات العروض محمية بتشفير TLS 1.3 أثناء النقل. المحتوى مشفر من طرف إلى طرف باستخدام AES-256-GCM مع مفاتيح ECDH فريدة لكل محادثة (منحنى P-256). المكالمات الصوتية والمرئية مشفرة باستخدام DTLS/SRTP عبر WebRTC. بياناتك مخزنة بشكل آمن في خوادم محمية مع تشفير أثناء التخزين."},{t:"حقوقك (GDPR و CCPA)",c:"لديك الحق في: الوصول إلى بياناتك، تعديلها، حذفها بالكامل، تصديرها (JSON مشفر)، والاعتراض على معالجتها. يمكنك حذف حسابك وجميع بياناتك بالكامل من صفحة الملف الشخصي. الحذف نهائي وغير قابل للاسترجاع ويشمل: الرسائل، بطاقات العروض، روابط الوكالة، ومفاتيح التشفير."},{t:"ملفات تعريف الارتباط",c:"نستخدم ملفات تعريف الارتباط الأساسية فقط لتشغيل التطبيق (الجلسة والمصادقة، مفاتيح التشفير). لا نستخدم ملفات تتبع أو إعلانية أو ملفات طرف ثالث."},{t:"الأطفال (COPPA)",c:"التطبيق مخصص للبالغين (18 عاماً فأكثر) للاستخدام التجاري. لا نجمع بيانات من الأطفال دون سن 18 عاماً عن علم. إذا اكتشفنا حساباً لقاصر، سنحذفه فوراً."},{t:"مشاركة البيانات",c:"لا نبيع بياناتك. قد نشارك بيانات مجهولة الهوية ومجمعة لأغراض التحليل الإحصائي الداخلي فقط. قد نكشف عن معلومات استجابة لأمر قضائي أو طلب قانوني ملزم. الوكلاء المفوضون يرون محادثات وعروض المشهور الذي يديرونه فقط، والتفويض قابل للإلغاء في أي وقت من قبل المشهور."},{t:"الأمان",c:"نستخدم أفضل الممارسات الأمنية: تشفير البيانات أثناء النقل (TLS 1.3) والتخزين، حماية من هجمات DDoS وSQL Injection وXSS، مراقبة مستمرة للنظام، نسخ احتياطي مشفر، وسياسات Row Level Security صارمة على قاعدة البيانات عبر Supabase."},{t:"الاحتفاظ بالبيانات",c:"نحتفظ ببياناتك طالما كان حسابك نشطاً. بعد حذف الحساب، يتم حذف جميع البيانات فوراً من أنظمتنا الأساسية والنسخ الاحتياطية خلال 30 يوماً. الرسائل المحذوفة من قبل المستخدم تُحذف فوراً من جهازه وتوضع في قائمة الحذف للطرف الآخر."},{t:"الإشعارات المرسلة",c:"الإشعارات المرسلة (Push) اختيارية وتحتوي فقط على: اسم المرسل، نوع الرسالة (نص، صوت، صورة)، ومحتوى مختصر. لا يتم إرسال محتوى الرسالة الكامل أو بطاقة العرض عبر خدمة الإشعارات. يمكنك تعطيل الإشعارات في إعدادات الجهاز."},{t:"التغييرات على هذه السياسة",c:"سنخطرك بأي تغييرات جوهرية عبر إشعار داخل التطبيق. استمرارك في استخدام التطبيق بعد التحديث يعني موافقتك على السياسة المحدّثة."},{t:"التواصل معنا",c:"لأي استفسارات حول الخصوصية: privacy@directly.app"}]:[{t:"Introduction",c:"Sovereign respects your privacy. We are committed to protecting your personal data in accordance with the highest international standards including GDPR (EU) and CCPA (California). Sovereign is a business communication platform for celebrities, agents, and companies — no public messages, no social feed, no free-form direct messages without an accepted Deal Card."},{t:"Data We Collect",c:"We collect the following to provide the service: email address, username, display name, profile photo, sent/received messages (end-to-end encrypted), Deal Cards and their details (deal type, company name, budget range, timeline, deliverables, exclusivity, rationale), agency links between celebrities and agents, public encryption keys, and account settings. We do NOT collect: location data, contacts, call logs, payment data, or any other sensitive data."},{t:"How We Use Your Data",c:"We use your data only for: providing business communication and Deal Card management, classifying incoming messages to Work Inbox using AI, sending push/email notifications for new offers and messages, preventing abuse and enforcing send limits in Work Inbox, and enabling agent delegation for conversation management on behalf of celebrities. We never sell or share your data with third parties for advertising."},{t:"AI & Message Classification",c:"We use AI only to classify incoming messages to the Work Inbox. Classification is performed temporarily on message content; original text is not stored after classification. We do not use your messages or Deal Cards to train AI models."},{t:"Message Encryption",c:"All messages and Deal Cards are protected with TLS 1.3 encryption in transit. Content is end-to-end encrypted using AES-256-GCM with unique ECDH keys per conversation (P-256 curve). Voice and video calls are encrypted using DTLS/SRTP via WebRTC. Your data is stored securely on protected servers with encryption at rest."},{t:"Your Rights (GDPR & CCPA)",c:"You have the right to: access, modify, delete, export (encrypted JSON), and object to processing of your data at any time. You can delete your account and all data permanently from the Profile page. Deletion is final and irreversible and includes: messages, Deal Cards, agency links, and encryption keys."},{t:"Cookies",c:"We use only essential cookies to operate the app (session, authentication, encryption keys). We do not use tracking, advertising, or third-party cookies."},{t:"Children (COPPA)",c:"The app is intended for adults (18+) for business use. We do not knowingly collect data from children under 18. If we discover a minor's account, we will delete it immediately."},{t:"Data Sharing",c:"We do not sell your data. We may share anonymized, aggregated data for internal statistical analysis only. We may disclose information in response to a court order or binding legal request. Delegated agents only see conversations and offers for the celebrity they manage, and delegation is revocable at any time by the celebrity."},{t:"Security",c:"We use industry-best security practices: data encryption in transit (TLS 1.3) and at rest, DDoS/SQL Injection/XSS protection, continuous system monitoring, encrypted backups, and strict Row Level Security policies on the database via Supabase."},{t:"Data Retention",c:"We retain your data while your account is active. After account deletion, all data is immediately removed from primary systems and backups within 30 days. Messages deleted by a user are immediately removed from their device and marked for deletion for the other party."},{t:"Push Notifications",c:"Push notifications are optional and contain only: sender name, message type (text, voice, image), and a brief preview. Full message content or Deal Card data is never sent via the notification service. You can disable notifications in device settings."},{t:"Changes to This Policy",c:"We will notify you of any material changes via an in-app notification. Continued use of the app after an update constitutes acceptance of the updated policy."},{t:"Contact Us",c:"For any privacy inquiries: privacy@directly.app"}];return e.jsxs("div",{className:"min-h-screen bg-background",dir:t?"rtl":"ltr",children:[e.jsx("header",{className:"fixed top-0 right-0 left-0 z-50 bg-card/95 backdrop-blur-sm border-b border-border",children:e.jsxs("div",{className:"max-w-lg mx-auto flex h-14 items-center gap-3 px-4",children:[e.jsx(c,{variant:"ghost",size:"icon",onClick:()=>i(-1),className:"h-10 w-10 rounded-xl",children:t?e.jsx(l,{className:"h-5 w-5"}):e.jsx(m,{className:"h-5 w-5"})}),e.jsx("h1",{className:"font-bold text-lg",children:t?"سياسة الخصوصية":"Privacy Policy"})]})}),e.jsxs("main",{className:"max-w-lg mx-auto pt-16 pb-24 px-4 space-y-6",children:[e.jsx("p",{className:"text-sm text-muted-foreground",children:t?"آخر تحديث: مارس 2026":"Last updated: March 2026"}),n.map((a,o)=>e.jsxs("section",{children:[e.jsx("h2",{className:"text-base font-bold mb-2",children:a.t}),e.jsx("p",{className:"text-sm text-muted-foreground leading-relaxed",children:a.c})]},o))]}),e.jsx(r,{})]})}export{D as default};
